const items = $input.all();

const requiredFields = [
  "Date",
  "Transaction_ID",
  "Product",
  "Category",
  "Sales",
  "Cost",
  "Profit",
  "Quantity",
  "Customer_ID"
];

const validItems = [];
const invalidItems = [];

for (const item of items) {

  const data = item.json;

  const missing = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      String(data[field]).trim() === ""
  );

  if (missing.length === 0) {
    validItems.push(data);
  } else {
    invalidItems.push({
      transaction_id: data.Transaction_ID || "Unknown",
      missing_fields: missing
    });
  }
}

return [
  {
    json: {
      data_valid: invalidItems.length === 0,
      total_records: items.length,
      valid_records: validItems.length,
      invalid_records: invalidItems.length,
      invalid_details: invalidItems,
      business_data: validItems
    }
  }
];

const data = $json.business_data;

const salesValues = data.map(item => Number(item.Sales));

const averageSales =
  salesValues.reduce((sum, value) => sum + value, 0)
  / salesValues.length;

const anomalies = [];

for (const item of data) {

  const sales = Number(item.Sales);

  let anomalyType = null;
  let severity = null;

  if (sales > averageSales * 2) {
    anomalyType = "UNUSUALLY HIGH SALES";
    severity = "HIGH";
  } 
  else if (sales < averageSales * 0.3) {
    anomalyType = "UNUSUALLY LOW SALES";
    severity = "MEDIUM";
  }

  if (anomalyType) {
    anomalies.push({
      ...item,
      anomaly_type: anomalyType,
      severity: severity
    });
  }
}

return [
  {
    json: {
      average_sales: Number(averageSales.toFixed(2)),
      anomaly_count: anomalies.length,
      anomaly_data: anomalies
    }
  }
];

const data = $json;

let result = data.output;

if (typeof result !== "string") {
  result = JSON.stringify(result);
}

result = result
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(result);
} catch (error) {
  throw new Error("Invalid JSON returned by AI");
}

return {
  json: {
    ...parsed
  }
};
